<?php ob_start();?><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2">Gestão do portfólio</h1><p class="text-white-50">Total: <?=count($projects)?> | Publicados: <?=count(array_filter($projects,static fn($p)=>!empty($p['published'])))?></p></div><a class="btn btn-info" href="<?=htmlspecialchars(base_url('admin/projeto'))?>">+ Novo projeto</a></div><?php if($flash):?><div class="alert alert-success"><?=htmlspecialchars($flash)?></div><?php endif;?><div class="table-responsive"><table class="table table-bordered align-middle"><thead><tr><th>Projeto</th><th>Categoria</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($projects as $p):?><tr><td><?=htmlspecialchars((string)$p['title'])?></td><td><?=htmlspecialchars((string)$p['category'])?></td><td><?=!empty($p['published'])?'Publicado':'Rascunho'?></td><td><div class="d-flex gap-2 flex-wrap"><a class="btn btn-sm btn-outline-info" href="<?=htmlspecialchars(base_url('admin/projeto?id='.urlencode((string)$p['id'])))?>">Editar</a><form method="post" action="<?=htmlspecialchars(base_url('admin/projeto/status'))?>"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(\App\Core\Csrf::token())?>"><input type="hidden" name="id" value="<?=htmlspecialchars((string)$p['id'])?>"><button class="btn btn-sm btn-outline-warning"><?=!empty($p['published'])?'Despublicar':'Publicar'?></button></form><button type="button" class="btn btn-sm btn-outline-danger" data-bs-toggle="modal" data-bs-target="#deleteModal" data-id="<?=htmlspecialchars((string)$p['id'])?>" data-title="<?=htmlspecialchars((string)$p['title'])?>">Excluir</button></div></td></tr><?php endforeach;?></tbody></table></div><div class="modal fade" id="deleteModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content bg-dark text-light"><div class="modal-header"><h2 class="modal-title fs-5">Confirmar exclusão</h2><button class="btn-close btn-close-white" data-bs-dismiss="modal" aria-label="Fechar"></button></div><div class="modal-body">Deseja excluir definitivamente <strong id="projectTitle"></strong>?</div><div class="modal-footer"><button class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button><form method="post" action="<?=htmlspecialchars(base_url('admin/projeto/excluir'))?>"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(\App\Core\Csrf::token())?>"><input type="hidden" id="deleteId" name="id"><button class="btn btn-danger">Sim, excluir</button></form></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>document.getElementById('deleteModal').addEventListener('show.bs.modal',e=>{const b=e.relatedTarget;document.getElementById('deleteId').value=b.dataset.id;document.getElementById('projectTitle').textContent=b.dataset.title;});</script><?php $content=ob_get_clean();$title='Portfólio';require __DIR__.'/layout.php';